extern "C" void render(const double* points,int n,float* out,int res,double scale){
 double rx=points[0],ry=points[1],th=atan2(points[4]-ry,points[3]-rx),w=0,d=0;
 const double mmpp=0.22185986964255727;
 for(int i=0;i<n;i++){
  double x=points[i*3],y=points[i*3+1],z=points[i*3+2];
  double zz=std::min(15.,std::max(0.,z)), W=z>0?std::max(0.,1.187*zz-.3)/mmpp:0,D=z>0?(1.38+1.075*zz)/mmpp:0;
  double O=z>0?std::max(0.,11.15-.0967*(zz-10.91)*(zz-10.91))/mmpp:0;
  w=.02*w+.98*W;d=.02*d+.98*D;
  double dx=x-rx,dy=y-ry,L=hypot(dx,dy),o=std::min(O,L);
  if(L>(z>0?1.:.1)/mmpp) th=atan2(dy,dx);
  if(L>0){rx=x-dx*o/L;ry=y-dy*o/L;}
  if(z<=0||w<.0001)continue;
  double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
  double x0=rx-w*.5*nx,x1=rx+w*.5*nx,x2=x0-d*ex,x3=x1-d*ex;
  double y0=ry-w*.5*ny,y1=ry+w*.5*ny,y2=y0-d*ey,y3=y1-d*ey;
  int u0=std::max(0,(int)floor(std::min({x0,x1,x2,x3})*scale)-1),u1=std::min(res-1,(int)ceil(std::max({x0,x1,x2,x3})*scale)+1);
  int v0=std::max(0,(int)floor(std::min({y0,y1,y2,y3})*scale)-1),v1=std::min(res-1,(int)ceil(std::max({y0,y1,y2,y3})*scale)+1);
  for(int v=v0;v<=v1;v++)for(int u=u0;u<=u1;u++){
   double qx=(u+.5)/scale-.5-rx,qy=(v+.5)/scale-.5-ry;
   double s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
   float a=std::max(0.,std::min(1.,std::min(s,f/g)*scale+.5));
   out[v*res+u]=std::max(out[v*res+u],a);
  }
 }
}
